"""Write README.md and LICENSE.txt for InteriorModels from models.json / sources.json. gen_text.py PACK_DIR"""
import sys, os, json
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from pack_meta import *
PACK = sys.argv[1]
mj = json.load(open(os.path.join(PACK, 'models.json')))['models']
sj = json.load(open(os.path.join(PACK, 'sources.json')))
total = sum(os.path.getsize(os.path.join(r, f)) for r, _, fs in os.walk(PACK) for f in fs)

def maps_of(e):
    out = []
    for mn, m in e['materials'].items():
        if m.get('glass'): out.append('%s: glass constant (d %.2f)' % (mn, m.get('d', 0.3)))
        elif m.get('Color'):
            ks = [k[0] for k in ('Color', 'Normal', 'MetallicSmoothness') if m.get(k)]
            out.append('%s: %s' % (mn, '+'.join({'C': 'C (cut-out alpha)' if m.get('alpha_cutoff') else 'C', 'N': 'N', 'M': 'MS'}[k] for k in ks)))
        else:
            out.append('%s: constant' % mn)
    return '; '.join(out)

def src_of(name, e):
    if name in PH: return 'Poly Haven `%s` (%s)' % (PH[name][0], PH[name][2])
    return 'Project-made'

cats = ['Seating', 'Tables', 'Soft furnishing', 'Plants', 'Decor', 'Wall', 'Lighting', 'Office', 'Storage', 'Security', 'Appliances', 'Safety', 'Building']
